FUNCTION_BLOCK FB_QualificationTestLimit EXTENDS FB_TestSuite
VAR_OUTPUT
	GuardPass : BOOL;
	CountBefore : UINT;
	OrderedBefore : UINT;
	CursorBefore : UDINT;
	BudgetBefore : UDINT;
	LastBefore : ST_CoUnitTestRecord;
	CountAfter : UINT;
	OrderedAfter : UINT;
	CursorAfter : UDINT;
	BudgetAfter : UDINT;
	LastAfter : ST_CoUnitTestRecord;
END_VAR
VAR
	_index : UINT;
	_name : T_MaxString;
END_VAR

PROGRAM PRG_Qualification
VAR_OUTPUT
	Done : BOOL;
	OraclePass : BOOL;
	FailedCheck : UDINT;
	SnapshotBytes : UDINT;
END_VAR
VAR
	_suite1 : FB_QualificationTestLimit;
	_snapshot : REFERENCE TO ST_CoUnitRunSnapshot;

END_VAR
